package com.example.techfix.ui;
import android.view.*; import android.widget.*; import androidx.recyclerview.widget.RecyclerView; import com.example.techfix.R; import java.util.*;
public class AdminAppointmentAdapter extends RecyclerView.Adapter<AdminAppointmentAdapter.ViewHolder>{ public interface Listener{void onUpdate(AdminAppointmentDisplay a,String status);} private final List<AdminAppointmentDisplay> list; private final Listener listener; private final String[] statuses={"Pending","In Progress","Completed"}; public AdminAppointmentAdapter(List<AdminAppointmentDisplay> l,Listener x){list=l;listener=x;} public static class ViewHolder extends RecyclerView.ViewHolder{TextView customer,service,branchDate;Spinner spinner;Button update;ViewHolder(View v){super(v);customer=v.findViewById(R.id.tvAdminCustomer);service=v.findViewById(R.id.tvAdminService);branchDate=v.findViewById(R.id.tvAdminBranchDate);spinner=v.findViewById(R.id.spinnerStatus);update=v.findViewById(R.id.btnUpdateStatus);}} @Override public ViewHolder onCreateViewHolder(ViewGroup p,int t){return new ViewHolder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_admin_appointment,p,false));} @Override public void onBindViewHolder(ViewHolder h,int pos){AdminAppointmentDisplay a=list.get(pos);h.customer.setText(a.getCustomerName());h.service.setText(a.getServiceName());h.branchDate.setText(a.getBranchName()+" — "+a.getDate());h.spinner.setAdapter(new ArrayAdapter<>(h.itemView.getContext(),android.R.layout.simple_spinner_dropdown_item,statuses));int i=Math.max(0,Arrays.asList(statuses).indexOf(a.getStatus()));h.spinner.setSelection(i);h.update.setOnClickListener(v->listener.onUpdate(a,(String)h.spinner.getSelectedItem()));} @Override public int getItemCount(){return list.size();}}
